export const citySlugs: Record<string,string> = {bangalore:"Bengaluru",bengaluru:"Bengaluru",hyderabad:"Hyderabad",pune:"Pune",mumbai:"Mumbai",delhi:"Delhi NCR",chennai:"Chennai",ahmedabad:"Ahmedabad"};
export const cityToSlug = (city: string) => city
  .toLowerCase()
  .normalize("NFKD")
  .replace(/[^a-z0-9]+/g, "-")
  .replace(/^-+|-+$/g, "");

