const allStartupRecords = [...featuredStartups, ...additionalStartups, ...bulkStartups, ...directoryStartups, ...directoryStartups2, ...directoryStartups3, ...directoryStartups4, ...directoryStartups5, ...directoryStartups6, ...directoryStartups7, ...bangaloreMapStartups, ...remoteDirectoryStartups, ...targetTechStartups]
  .filter((startup) => startup.slug !== "ensembl")
  .map((startup) => {
    const override=locationOverrides[startup.slug as keyof typeof locationOverrides];
    return {
      ...startup,
      ...(override?{city:override.city,neighborhood:override.city,lat:override.lat,lng:override.lng,locationPrecision:"CITY" as const,locationSource:override.source}:{}),
      logoUrl: `https://www.google.com/s2/favicons?domain_url=${encodeURIComponent(startupLinks[startup.slug].website)}&sz=128`,
      isDemo: false,
    };
  });

export const startups = allStartupRecords.filter((startup,index,records)=>records.findIndex(item=>item.slug===startup.slug)===index);
export const mappedStartups = startups.filter(startup=>startup.city!=="India");
export const locationUnverifiedStartups = startups.filter(startup=>startup.city==="India");

